  "supersedes": [
    "2024-06-28"
  ],
  "changes": [
    {
      "change_id": "c1",
      "scheme_id": "mh.ladki_bahin",
      "change_type": "parameter_update",
      "target": "age_max",
      "summary": "The maximum age for applicants rises from 60 to 65 completed years.",
      "old_value": "60",
      "new_value": "65",
      "boundary": "inclusive",
      "effective_from": "2024-07-03",
      "affects": "widens",
