        "page": 2,
        "clause": "4(3)",
        "quote_original": "किमान वयाची २१ वर्षे पूर्ण व कमाल वयाची ६५ वर्षे पूर्ण होईपर्यंत",
        "quote_english": "Minimum age 21 years completed and maximum age 65 years completed"
      },
      "confidence": 0.9
    },
    {
      "change_id": "c2",
      "scheme_id": "mh.ladki_bahin",
      "change_type": "parameter_update",
      "target": "disqualifying_govt_jobs",
      "summary": "Contract government employees are no longer a disqualifying job type; outsourced, volunteer and contract workers are eligible if family income is up to Rs 2.5 lakh.",
      "old_value": "[\"regular\", \"contract\", \"pensioner\"]",
      "new_value": "[\"regular\", \"pensioner\"]",
